def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+\-*/,:=<>]")
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "NEG": 3,
        ":": 4,
    }

    def parse(text):
        tokens = token_pattern.findall(text)
        values = []
        operators = []
        commas = []

        def apply_operator():
            op = operators.pop()
            if op == "NEG":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("op", op, left, right))

        expect_operand = True
        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(("num", int(token)))
                expect_operand = False
            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                values.append(("cell", token))
                expect_operand = False
            elif token == "(":
                operators.append(token)
                commas.append(0)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    apply_operator()
                commas[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    apply_operator()
                operators.pop()
                count = commas.pop() + 1
                if operators and operators[-1] in ("SUM", "MIN", "MAX", "IF"):
                    function = operators.pop()
                    args = values[-count:]
                    del values[-count:]
                    values.append(("func", function, args))
                expect_operand = False
            else:
                op = "NEG" if token == "-" and expect_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "NEG"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expect_operand = True
            i += 1

        while operators:
            apply_operator()
        return values[0]

    parsed = {}
    results = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    values.append(0)
                elif name in results:
                    values.append(results[name])
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    tasks.append(("finish_cell", name))
                    content = cells[name]
                    if content.startswith("="):
                        if name not in parsed:
                            parsed[name] = parse(content[1:])
                        tasks.append(("eval", parsed[name]))
                    else:
                        values.append(int(content))

            elif kind == "finish_cell":
                name = task[1]
                active.remove(name)
                results[name] = values[-1]

            elif kind == "eval":
                node = task[1]
                node_type = node[0]

                if node_type == "num":
                    values.append(node[1])
                elif node_type == "cell":
                    tasks.append(("cell", node[1]))
                elif node_type == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_type == "op":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        items = []
                        for arg in args:
                            if arg[0] == "op" and arg[1] == ":":
                                first, last = arg[2][1], arg[3][1]
                                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                                for row in range(row1, row2 + 1):
                                    for col in range(col1, col2 + 1):
                                        name = chr(col) + str(row)
                                        if name in cells:
                                            items.append(("cell", name))
                            else:
                                items.append(("eval", arg))
                        tasks.append(("aggregate", function, items, 0, None))

            elif kind == "neg":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                elif op == "+":
                    values.append(left + right)
                elif op == "-":
                    values.append(left - right)
                elif op == "*":
                    values.append(left * right)
                elif op == "/":
                    if right == 0:
                        values.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        values.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    values.append(left == right)
                elif op == "<>":
                    values.append(left != right)
                elif op == "<":
                    values.append(left < right)
                elif op == "<=":
                    values.append(left <= right)
                elif op == ">":
                    values.append(left > right)
                else:
                    values.append(left >= right)

            elif kind == "if_condition":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, items, index, accumulator = task[1:]
                if index == len(items):
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("aggregate_value", function, items, index, accumulator))
                    tasks.append(items[index])

            else:  # aggregate_value
                function, items, index, accumulator = task[1:]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", function, items, index + 1, accumulator))

        return values.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
